import logging


class MbmsApp:
    """MBMS Application"""

    def __init__(self, configuration, ue):
        """

        :param configuration:
        :param ue:
        """
        self.ue = ue
        self._configuration = configuration
        if 'ue_logger_name' in self._configuration:
            self.logger = logging.getLogger(self._configuration['ue_logger_name'])
        else:
            self.logger = logging.getLogger('ute_ue')

    def start(self, sessions):
        """
        Starts mbms application with parameters defined in config passed during initialization.
        :return: None
        """
        raise NotImplementedError

    def stop(self):
        """
        Stops already running mbms application.

        Fires exception if application was not started yet.
        No action if application is already stopped.
        :return: None
        """
        raise NotImplementedError
